INSERT INTO analyses (trend_id, recommandation, explication, modele) VALUES ('yuzu', 'ignorer', 'La tendance du yuzu semble en déclin depuis son pic d''intérêt en mai 2023. Les données montrent une croissance négative sur les cinq dernières années et les douze derniers mois, ce qui suggère que cette tendance pourrait ne pas être durable. La confiance des données est élevée grâce aux sources multiples comme Google Trends, Wikipedia et la presse. Il serait préférable d''utiliser l''arôme bergamote en raison de sa disponibilité élevée et de son coût plus abordable. Si le yuzu reste sous tension, il faudrait envisager le développement d''un arôme yuzu ou attendre que la tendance se stabilise.', 'qwen2.5:7b (équipe Data)');
INSERT INTO analyses (trend_id, recommandation, explication, modele) VALUES ('serum-peptides', 'suivre', 'La tendance du peptide serum a connu une croissance significative ces dernières années, mais elle se situe actuellement sur un plateau. Les sources et les médias ne montrent pas encore de forte diffusion, ce qui peut indiquer que la tendance pourrait s''essouffler. Cependant, l''intérêt persiste depuis 2026-03-01. Utilisez le Complexe peptides (actif beauté) de Givaudan pour capitaliser sur cette tendance en croissance. Si la matière est sous tension, envisagez d''attendre ou de développer un nouvel arôme adaptatif.', 'qwen2.5:7b (équipe Data)');
INSERT INTO analyses (trend_id, recommandation, explication, modele) VALUES ('matcha', 'attendre', 'La tendance du matcha semble en déclin selon les données, avec une croissance de l''intérêt qui a diminué de 27% sur un an. Bien que le pic d''intérêt soit prévu pour avril 2025, la confiance des données est élevée et indique une probabilité faible que cette tendance se maintienne à long terme. Utilisez l''arôme thé vert en cas de tension sur les ressources. Si le matcha devient trop rare ou coûteux, développez un arôme pour hojicha ou attendez la disponibilité d''un autre arôme de matcha.', 'qwen2.5:7b (équipe Data)');
INSERT INTO analyses (trend_id, recommandation, explication, modele) VALUES ('pistache-gourmande', 'attendre', 'La tendance de l''intérêt pour la pistache semble être en déclin selon les données fournis. Le pic d''intérêt a été atteint en mars 2025 et le score de durabilité est bas, ce qui suggère que cette tendance pourrait ne pas se maintenir à long terme. Les alternatives proposées sont plus stables et moins risquées. Utilisez l''arôme noisette torréfiée en priorité car il est disponible et moins coûteux. Si la matière première pour la pistache reste sous tension, développez un arôme de pistache synthétique ou attendez que les conditions se stabilisent.', 'qwen2.5:7b (équipe Data)');
INSERT INTO analyses (trend_id, recommandation, explication, modele) VALUES ('kombucha', 'ignorer', 'La tendance du kombucha est en déclin selon les données, avec une croissance de l''intérêt qui a fortement baissé sur 12 mois. Cela suggère que le marché peut être saturé et qu''il vaut mieux se tourner vers d''autres arômes pour éviter un risque élevé. Utilisez l''arôme thé vert, car il est disponible rapidement et à un coût raisonnable. Si la matière devient sous tension, envisagez le développement de l''arôme thé hojicha comme alternative.', 'qwen2.5:7b (équipe Data)');
INSERT INTO analyses (trend_id, recommandation, explication, modele) VALUES ('dubai-chocolate', 'ignorer', 'La tendance du chocolat de Dubaï semble en déclin selon les données fournies. L''intérêt a diminué de -79% sur 12 mois et le pic d''intérêt est passé, ce qui suggère que cette tendance pourrait ne pas être durable. Cependant, la croissance de l''intérêt sur 5 ans reste positive à 55%, indiquant une certaine stabilité dans l''avenir proche. Utilisez l''arôme noisette torréfiée ou l''arôme amande, qui sont disponibles et moins coûteux. Si la matière première est sous tension, développez un arôme de chocolat de Dubai adaptatif ou attendez une stabilisation de cette tendance.', 'qwen2.5:7b (équipe Data)');
INSERT INTO analyses (trend_id, recommandation, explication, modele) VALUES ('ube', 'suivre', 'La tendance de l''ube a atteint son pic d''intérêt et continue à croître, mais au rythme ralenti. Avec une diffusion modérée et des sources limitées, la confiance dans les données est élevée. Cependant, le stade plateau suggère que cette tendance pourrait se stabiliser ou même décroitre. Il est recommandé de développer l''arôme ube (igname violette) pour profiter du potentiel de croissance restant. Si la disponibilité et le coût sont des préoccupations, une alternative comme la patate douce rôtie pourrait être envisagée.', 'qwen2.5:7b (équipe Data)');
COMMIT;
